<?php
if(!defined('ABSPATH')){exit;}if(!current_user_can(SPF_Roles::USERS)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para consultar roles.','sistema-para-farmacias'));}$definitions=SPF_Roles::role_definitions();$labels=SPF_Roles::capability_labels();
?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Roles y permisos','sistema-para-farmacias'); ?></h1><div class="spf-panel"><p><?php esc_html_e('Estos perfiles se asignan desde Usuarios de WordPress. Los identificadores históricos se mantienen para que una instalación anterior conserve usuarios y permisos.','sistema-para-farmacias'); ?></p></div><div class="spf-panel"><div class="spf-table-scroll spf-table-wide"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Rol','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Uso recomendado','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Permisos','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php foreach($definitions as $key=>$data): ?><tr><td><strong><?php echo esc_html($data['name']); ?></strong><br><code><?php echo esc_html($key); ?></code></td><td><?php echo esc_html($data['description']); ?></td><td><?php foreach($data['caps'] as $cap): ?><span class="spf-capability-badge"><?php echo esc_html($labels[$cap]??$cap); ?></span><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="spf-panel"><h2><?php esc_html_e('Regla recomendada','sistema-para-farmacias'); ?></h2><p><?php esc_html_e('Los usuarios de caja o almacén no deberían ser administradores de WordPress. Asigna únicamente el perfil operativo que necesitan. Los administradores de WordPress reciben todas las capacidades del sistema.','sistema-para-farmacias'); ?></p></div></div>
